        sort(arr.begin(), arr.end());

        long long perimeter = 4LL * side;
        vector<long long> arrExt(2 * n);
        for (int i = 0; i < n; ++i) {
            arrExt[i] = arr[i];
            arrExt[i + n] = arr[i] + perimeter;
        }

        auto canPlace = [&](long long d) -> bool {
            for (int i = 0; i < n; ++i) {
                long long curr = arr[i];
                int count = 1;
                int idx = i;

                for (int step = 1; step < k; ++step) {
